def natural_sort_strings(strings):
    """Sort strings by natural order: digit runs compared as integers, non-digit runs case-sensitive Unicode order.
    Text tokens sort before numeric tokens when kinds differ. Shorter equal-prefix token lists sort first.
    Equal keys preserve input order. Empty strings allowed."""
    import functools

    @functools.cmp_to_key
    def compare(a, b):
        # Parse into runs of digits and non-digits
        def runs(s):
            res = []
            i = 0
            n = len(s)
            while i < n:
                if s[i].isdigit():
                    j = i
                    while j < n and s[j].isdigit():
                        j += 1
                    res.append(('digit', int(s[i:j])))
                    i = j
                else:
                    j = i
                    while j < n and not s[j].isdigit():
                        j += 1
                    res.append(('text', s[i:j]))
                    i = j
            return res

        ra = runs(a)
        rb = runs(b)

        # Compare token by token
        for ta, rb_ in zip(ra, rb):
            kind_a, val_a = ta
            kind_b, val_b = rb_
            if kind_a != kind_b:
                # Text tokens sort before numeric tokens
                if kind_a == 'text' and kind_b == 'digit':
                    return -1
                else:
                    return 1
            else:
                if kind_a == 'digit':
                    if val_a < val_b:
                        return -1
                    elif val_a > val_b:
                        return 1
                else:
                    if val_a < val_b:
                        return -1
                    elif val_a > val_b:
                        return 1
        # All compared tokens equal; shorter list sorts first
        if len(ra) < len(rb):
            return -1
        elif len(ra) > len(rb):
            return 1
        # Equal keys preserve input order
        return 0

    return sorted(strings, key=compare)
